
export class BodyScrollBlocker {
    private startY: number;

    private scrollingElement: HTMLElement;

    constructor(scrollingElement: HTMLElement) {
        this.scrollingElement = scrollingElement;
        this.startY = 0;

        this.onTouchStart = this.onTouchStart.bind(this);
        this.onTouchMove = this.onTouchMove.bind(this);

        this.scrollingElement.addEventListener('touchstart', this.onTouchStart, { passive: false });
        this.scrollingElement.addEventListener('touchmove', this.onTouchMove, { passive: false });
    }

    public removeListeners(): void {
        this.scrollingElement.removeEventListener('touchstart', this.onTouchStart);
        this.scrollingElement.removeEventListener('touchmove', this.onTouchMove);
    }

    private onTouchStart(event: TouchEvent): void {
        if (event.targetTouches.length === 1) {
            this.startY = event.targetTouches[0].clientY;
        }
    }

    private onTouchMove(event: TouchEvent): void {
        if (event.cancelable && event.targetTouches.length === 1) {
            const pixelsScrolled: number = this.startY - event.targetTouches[0].clientY;
            const scrollAtTop: boolean = this.scrollingElement.scrollTop <= 0;
            const scrollAtBottom: boolean = this.scrollingElement.scrollTop + this.scrollingElement.offsetHeight >= this.scrollingElement.scrollHeight;

            const overScrolledTop: boolean = scrollAtTop && pixelsScrolled < 0;
            const overScrolledBottom: boolean = scrollAtBottom && pixelsScrolled > 0;

            if (overScrolledTop || overScrolledBottom) {
                event.preventDefault();
            }
        }
    }
}
